    #[allow(clippy::too_many_arguments)]
    pub fn aim(&self, pal: &Palette, want: Rgb, (x, y): (f32, f32), r: f32, medium: f32, coats: f32) -> Paint {
        pal.paint_for(want, self.under(x, y, r), medium, coats)
