    pub fn from_shape(f: Frame, shape: Shape) -> Self {
        let mut m = Mask::empty(f);
        let paths = shape.paths();
        if !paths.is_empty() {
            let mut tm = tiny_skia::Mask::new(f.w as u32, f.h as u32).unwrap();
