use paint::{Canvas, Gesture, Held, Orient, Paint, Tool, hex};
fn main() {
    let mut c = Canvas::new(1000, 1.4, hex("#e8dcc0"));
    let p = Paint::new(hex("#3a3129"), 0.9, 0.5);
    let cases: Vec<(&str, Vec<(f32, f32)>)> = vec![
        ("down", vec![(100.0, 100.0), (100.0, 120.0)]),
        ("up", vec![(120.0, 120.0), (120.0, 100.0)]),
        ("V 3pt", vec![(140.0, 100.0), (143.0, 112.0), (147.0, 100.0)]),
        ("wide V", vec![(170.0, 100.0), (185.0, 115.0), (200.0, 100.0)]),
        ("hook", vec![(220.0, 100.0), (220.0, 115.0), (226.0, 115.0)]),
        ("down-then-up same x", vec![(240.0, 100.0), (240.0, 115.0), (240.5, 100.0)]),
        ("L-shape then up", vec![(260.0, 100.0), (260.0, 115.0), (270.0, 115.0), (270.0, 100.0)]),
    ];
    for tool in [Tool::rigger(0.45), Tool::round_sable(1.5)] {
        for (name, pts) in &cases {
            let mut h = Held::new(tool.clone(), 7);
            h.load(p, 0.5);
            let f0 = h.fullness();
            c.drag(&mut h, &Gesture::new(pts.clone()).pressure(0.55, 0.55).ramps(0.1, 0.1).orient(Orient::Across), None);
            println!("{:?} {:<22} {:.4} -> {:.4}", tool.kind, name, f0, h.fullness());
        }
    }
}
